package com.mo.economy_system.network;import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.check.ClientFileCheckType;import com.mo.economy_system.common.network.*;import io.netty.buffer.Unpooled;import java.util.UUID;import net.minecraft.network.FriendlyByteBuf;import org.junit.jupiter.api.Test;
class CheckedFileTransferWireCodecTest{@Test void roundTripsLegacyShapesAndRejectsTrailing(){UUID t=UUID.randomUUID(),r=UUID.randomUUID(),id=UUID.randomUUID();var request=new CheckedFileTransferRequestMessage("target",t,"requester",r,ClientFileCheckType.MODS,"a.jar");var b=new FriendlyByteBuf(Unpooled.buffer());CheckedFileTransferWireCodec.encodeRequest(request,b);assertEquals(request,CheckedFileTransferWireCodec.decodeRequest(b));var chunk=new CheckedFileTransferChunkRequestMessage("target",t,"requester",r,ClientFileCheckType.MODS,"a.jar",id,0,1,"YQ==");var chunkBuffer=new FriendlyByteBuf(Unpooled.buffer());CheckedFileTransferWireCodec.encodeChunkRequest(chunk,chunkBuffer);chunkBuffer.writeByte(1);assertThrows(RuntimeException.class,()->CheckedFileTransferWireCodec.decodeChunkRequest(chunkBuffer));}@Test void failedEncodeLeavesDestinationUntouched(){var b=new FriendlyByteBuf(Unpooled.buffer());b.writeInt(7);int before=b.writerIndex();assertThrows(RuntimeException.class,()->CheckedFileTransferWireCodec.encodeControlRequest(new CheckedFileTransferControlRequestMessage("target",UUID.randomUUID(),"requester",UUID.randomUUID(),ClientFileCheckType.MODS,"a","{}".repeat(2000)),b));assertEquals(before,b.writerIndex());}}
